# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLARLA İLETİŞİM İLKELERİ (PH.5.2.1)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sevgi ve Şefkat</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Çocukları kucaklar, başlarını</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">okşar ve öperdi.</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Torunları Hz. Hasan ve</text>\n  <text x="125" y="166" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Hz. Hüseyin\'i omzunda taşırdı.</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">«Merhamet etmeyene merhamet olunmaz.»</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Saygı ve Değer Verme</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Yolda karşılaştığı çocuklara</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">önce kendisi selam verirdi.</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11.5" fill="#14532d">• Meclislerde çocukların söz</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11.5" fill="#14532d">ve ikram hakkını korurdu.</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Çocuğu birey olarak muhatap alırdı.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Sabır, Tevazu ve Mizah</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Çocuklarla oyun oynar, yarışır</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#78350f">ve nezaketle şakalaşırdı.</text>\n  <text x="575" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Şaka yaparken bile doğrudan</text>\n  <text x="575" y="166" text-anchor="middle" font-size="11.5" fill="#78350f">ayrılmaz, kalp kırmazdı.</text>\n  <text x="575" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Hataları tatlı dille düzeltirdi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ASRISAADET\'TEN ÖRNEK OLAYLAR: ENES BİN MALİK VE EBÛ UMEYR</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hz. Enes bin Malik\'in (r.a.) Tanıklığı</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#831843">• Çocuk yaşta 10 yıl boyunca</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#831843">Peygamberimizin yanında bulundu.</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" fill="#831843">• «Yaptığım bir iş için \'Bunu niçin böyle</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" fill="#831843">yaptın?\' ya da yapmadığım bir iş için</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11.5" fill="#831843">\'Niçin yapmadın?\' diyerek beni azarlamadı.»</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Sabır ve hoşgörünün en güzel örneği</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Küçük Ebû Umeyr ve Kuşu «Nugayr»</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• Enes bin Malik\'in küçük kardeşi Ebû Umeyr\'in</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11.5" fill="#155e75">çok sevdiği «Nugayr» adlı serçe kuşu öldü.</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11.5" fill="#155e75">• Hz. Peygamber onun üzüntüsünü fark edip</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11.5" fill="#155e75">yanına oturdu ve «Ey Ebû Umeyr! Kuşun</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11.5" fill="#155e75">Nugayr ne oldu?» diyerek onu teselli etti.</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Çocuğun duygularını ciddiye alma ve empati</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZDA, YETİMLERE YAKLAŞIMDA VE EĞİTİMDE ŞEFKAT</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İbadette Kolaylık</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11.5" fill="#581c87">• Cemaatle namaz kıldırırken</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11.5" fill="#581c87">ağlayan bir çocuk sesi duysa</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11.5" fill="#581c87">annesi telaşlanmasın diye</text>\n  <text x="125" y="162" text-anchor="middle" font-size="11.5" fill="#581c87">namazı kısa tutardı.</text>\n  <text x="125" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Secdede torunlarını beklerdi.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yetimlere Kol Kanat Germe</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11.5" fill="#14532d">• Kendisi de yetim büyüdüğü</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">için yetim çocukları korur,</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">bayram sabahı ağlayan yetimi</text>\n  <text x="350" y="162" text-anchor="middle" fill-opacity="1" fill="#14532d">evine götürüp sevindirirdi.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Yetim gözetenle cennette komşuluk</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tatlı Dille Eğitim</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hurma ağaçlarını taşlayan</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Rafî bin Amr\'ın başını okşayıp</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11.5" fill="#1e3a8a">«Yavrucuğum, ağaca taş atma;</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11.5" fill="#1e3a8a">yere düşenleri ye» buyurdu.</text>\n  <text x="575" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Suçlamadan, dua ederek eğitme</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
